```python
def sum_squares(lst):
    if not lst:
        return 0
    result = 0
    for i, num in enumerate(lst):
        if i % 3 == 0 and i % 4 == 0:
            result += num ** 3
        elif i % 3 == 0:
            result += num ** 2
        elif i % 4 == 0:
            result += num ** 3
        else:
            result += num
    return result
```

