from typing import List

def is_sorted(lst: List[int]) -> bool:
    if not lst:
        return True
    if len(lst) == 1:
        return True
    for i in range(1, len(lst)):
        if lst[i] < lst[i-1]:
            return False
    if len(lst) != len(set(lst)):
        if len(lst) - len(set(lst)) > 1:
            return False
    return True
```

