from typing import List

def do_algebra(operator: List[str], operand: List[int]) -> int:
    if len(operator)!= len(operand) - 1:
        raise ValueError("The length of operator list must be equal to the length of operand list minus one")
    if not all(isinstance(op, str) for op in operator):
        raise ValueError("All elements in operator list must be strings")
    if not all(isinstance(num, int) and num >= 0 for num in operand):
        raise ValueError("All elements in operand list must be non-negative integers")

    result = operand[0]
    for i in range(len(operator)):
        if operator[i] == '+':
            result += operand[i + 1]
        elif operator[i] == '-':
            result -= operand[i + 1]
        elif operator[i] == '*':
            result *= operand[i + 1]
        elif operator[i] == '//':
            if operand[i + 1] == 0:
                raise ZeroDivisionError("Cannot divide by zero")
            result //= operand[i + 1]
        elif operator[i] == '**':
            result **= operand[i + 1]
        else:
            raise ValueError("Invalid operator")

    return result
```

