def match_parens(lst):
    def is_balanced(s):
        balance = 0
        for c in s:
            if c == '(':
                balance += 1
            else:
                balance -= 1
                if balance < 0:
                    return False
        return balance == 0

    for s1, s2 in [(lst[0], lst[1]), (lst[1], lst[0])]:
        balance = 0
        for c in s1:
            if c == '(':
                balance += 1
            else:
                balance -= 1
                if balance < 0:
                    break
        else:
            balance2 = balance
            for c in s2:
                if c == '(':
                    balance2 += 1
                else:
