        balance = 0
        for c in s1:
            if c == '(':
                balance += 1
            else:
                balance -= 1
                if balance < 0:
                    break
        else:
            balance2 = balance
            for c in s2:
                if c == '(':
                    balance2 += 1
                else:
                    balance2 -= 1
            if balance2 == 0:
                return 'Yes'
    return 'No'
