def is_prime(num: int) -> bool:
    """Check if a number is prime."""
    if num < 2:
        return False
    for i in range(2, int(num ** 0.5) + 1):
        if num % i == 0:
            return False
    return True

def prime_fib(n: int) -> int:
    """Return the n-th number that is a Fibonacci number and also prime."""
    if n < 1:
        raise ValueError("n must be a positive integer")

    a, b = 0, 1
    count = 0

    while True:
        a, b = b, a + b
        if is_prime(b):
            count += 1
            if count == n:
                return b

def main():
    print(prime_fib(1))  # 2
    print(prime_fib(2))  # 3
    print(prime_fib(3))  # 5
    print(prime_fib(4))  # 13
    print(prime_fib(5))  # 89

if __name__ == "__main__":
    main()
```

