import operator as op

def do_algebra(operators, operands):
    if not operators or not operands or len(operators) != len(operands) - 1:
        raise ValueError("Invalid input lists")

    operation_map = {
        '+': op.add,
        '-': op.sub,
        '*': op.mul,
        '//': op.floordiv,
        '**': op.pow
    }

    result = operands[0]
    for i, op_symbol in enumerate(operators):
        if op_symbol not in operation_map:
            raise ValueError("Unsupported operator")
        result = operation_map[op_symbol](result, operands[i + 1])

    return result
```

